const dec = a => { const o = []; for (let i = 0; i < a.length; i += 2) o.push([a[i]/2, a[i + 1]/2]); return o; };

// ---------- batches: triangles with a current colour, flat normals, chunked storage; one mesh per batch ----------
const CHUNK = 1 << 17;
