const resample = (pl, step) => { const out = [pl[0]]; for (let i = 0; i < pl.length - 1; i++){ const a = pl[i], b = pl[i + 1], L = Math.hypot(b[0] - a[0], b[1] - a[1]), n = Math.max(1, Math.ceil(L/step)); for (let k = 1; k <= n; k++) out.push([lerp(a[0], b[0], k/n), lerp(a[1], b[1], k/n)]); } return out; };
const gRange = P => { let lo = 1e9, hi = -1e9; for (const p of P){ const h = GY(p[0], p[1]); lo = Math.min(lo, h); hi = Math.max(hi, h); } const c = cen(P), hc = GY(c[0], c[1]); return [Math.min(lo, hc), Math.max(hi, hc)]; };
