const oIdx = (x, z) => { const i = Math.floor((x - OG.x0)/OG.c), j = Math.floor((z - OG.z0)/OG.c); return i < 0 || j < 0 || i >= OG.n || j >= OG.m ? -1 : j*OG.n + i; };
