    V.c('#f2efe8'); lathe(V, [[15.5, 0.08], [15.5, 1.15]], tx, y, tz, 16, a0, a1); lathe(V, [[9.5, 1.15], [9.5, 0.08]], tx, y, tz, 16, a0, a1);
