  const hs = []; for (let i = 0; i < 48; i++){ const a = i/48*TAU; for (const r of [AP.RI + 3, AP.RO - 3]) hs.push(GY(cx + Math.cos(a)*r, cz + Math.sin(a)*r)); }
  hs.sort((a, b) => a - b); AP.Y0 = hs[Math.floor(hs.length*0.8)] + 0.15;
  AP.YT = GY(AP.T[0], AP.T[1]) + AP.HM;
  const inside = (x, z) => inPoly(S.keep, x, z);
  occupy(S);
  // the ring and the theater hill in the occupancy grid
  { const ring = [], hole = []; for (let i = 0; i < 96; i++){ const a = i/96*TAU; ring.push([cx + Math.cos(a)*(AP.RO + 1), cz + Math.sin(a)*(AP.RO + 1)]); hole.push([cx + Math.cos(a)*(AP.RI - 1), cz + Math.sin(a)*(AP.RI - 1)]); } oPoly(ring, 1, [hole]); }
  { const d = []; for (let i = 0; i < 48; i++){ const a = i/48*TAU; d.push([AP.T[0] + Math.cos(a)*30, AP.T[1] + Math.sin(a)*30]); } oPoly(d, 1); }
  paintGround(S, [176, 196, 140]);
  apRing(); apTheater();
  for (const id of ['w491340789', 'w521662177', 'r5281838']){ const b = byId(S, id); if (b) b.done = true; }
  apVisitor(S); apFitness(S);
  for (const id of ['w518029226', 'w518029225']){ const b = byId(S, id); if (b) apGarage(b, 4, 3.55); }
  for (const b of S.b){ if (b.done) continue;
    if (b.id === 'w518046655') apBarn(b);
    else if (b.id === 'w744204115') apStage(b);
    else if (b.id === 'w518037434') apPavilion(b, {h:10.2, stone:'#c9c6bf', over:0.6, plinth:'#c2bfb8'});
    else if (b.name === 'Outdoor Food Station') apPavilion(b, {h:4.6, over:2.4});
    else if (/Reception/.test(b.name)) apPavilion(b, {h:Math.max(5, b.h), over:2.0, mid:0});
    else apPavilion(b, {h:Math.max(3.2, b.h), over:0.9}); }
  ponds(S, inside);
  // paths over our raised ground (the real ones are drawn on the real ground, under the hill / terraces)
  for (const r of S.roads){ if (r.cls < 11) continue; const pts = resample(r.pts, 3), w = r.cls === 11 ? 3.0 : 1.3;
    for (let i = 0; i < pts.length - 1; i++){ const a = pts[i], b = pts[i + 1], ha = apMound(a[0], a[1]), hb = apMound(b[0], b[1]); if (ha < GY(a[0], a[1]) + 0.25 && hb < GY(b[0], b[1]) + 0.25) continue;
      const L = Math.hypot(b[0] - a[0], b[1] - a[1]) || 1, nx = -(b[1] - a[1])/L*w, nz = (b[0] - a[0])/L*w;
      M.v.c('#ddd7cb'); M.v.q([a[0] - nx, ha + 0.08, a[1] - nz], [b[0] - nx, hb + 0.08, b[1] - nz], [b[0] + nx, hb + 0.08, b[1] + nz], [a[0] + nx, ha + 0.08, a[1] + nz]); } }
  // trees: the woods (oaks), orchard rows, scattered valley oaks in the meadows, the rest of the landscape
  let nT = 0; const T = (x, z, s, k) => { if (!inside(x, z)) return false; const o = oGet(x, z); if (o && o !== 8) return false;
    const r = Math.hypot(x - cx, z - cz), raised = apRaised(x, z), g = GY(x, z);
    if (r > AP.RI - 2 && r < AP.RO + 2) return false;
    if (raised > g + 0.35){
      if (Math.hypot(x - AP.T[0], z - AP.T[1]) < 30) return false;
      if (apBerm(r) > g + 0.35 && r < AP.RO + 9.5 && r > AP.RI - 8) return false;
      ownTree(x, raised, z, s*0.85, k === 'pine' ? '#3f6650' : '#5f8a4c'); nT++; return true; }
    CTX.tree(x, z, s, k); nT++; const q = oIdx(x, z); if (q >= 0) OG.a[q] = 10; return true; };
  plantArea(S.a.forest, 8.5, (x, z) => T(x, z, 3.2 + R()*1.8, kindOf([['d', 0.56], ['raintree', 0.34], ['pine', 0.10]])));
  for (const a of S.a.orchard){ const ob = obb(a.ring), F = rotP2(ob.cx, ob.cz, ob.ry);
    for (let u = -ob.L/2 + 3; u < ob.L/2; u += 5.5) for (let v = -ob.W/2 + 3; v < ob.W/2; v += 6){ const p = F(u, 0, v); if (inPoly(a.ring, p[0], p[2])) T(p[0], p[2], 1.7 + R()*0.4, R() < 0.8 ? 'd' : 'clipped'); } }
