// ---------- parked cars in the surface lots ----------
const CARS = ['#e8e8e6', '#2c2f33', '#9aa0a6', '#7d1f1f', '#20385a', '#c7c9cb', '#4a4f55', '#f1f0ea', '#5c6670', '#c7c2b2'];
